import{_ as r,C as i,o as a,c as s,a6 as t,b as l,w as n,a as h,E as d,ae as c}from"./chunks/framework.BHBQfcoO.js";const u="/img/msd-routing-obstacle-avoidance.svg",g="/img/msd-routing-trunk-bundling.svg",p="/img/msd-routing-channel-prefer.svg",m="/img/msd-routing-crossing-avoidance.svg",E=JSON.parse('{"title":"Routing Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"cards/msd/routing-concepts.md","filePath":"cards/msd/routing-concepts.md"}'),f={name:"cards/msd/routing-concepts.md"};function b(C,e,y,w,_,v){const o=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="routing-concepts" tabindex="-1">Routing Concepts <a class="header-anchor" href="#routing-concepts" aria-label="Permalink to &quot;Routing Concepts&quot;">​</a></h1><p>MSD lines route themselves like <strong>cable raceways</strong> on a circuit board: they find their own way around obstacles, bundle together when they&#39;re heading the same direction, and avoid cutting across each other when a small detour is cheap enough. This page is the short version of <em>how the router decides a path</em>: a mental model, not the full config reference.</p><div class="tip custom-block"><p class="custom-block-title">Just want the config knobs?</p><p>This page explains the concepts. For every mode, field, and tunable default, see <a href="./routing.html">Line Routing &amp; Channels</a>.</p></div><hr><h2 id="the-decision-flow" tabindex="-1">The Decision Flow <a class="header-anchor" href="#the-decision-flow" aria-label="Permalink to &quot;The Decision Flow&quot;">​</a></h2><p>For every line, on every recompute, the router works through the same sequence:</p>',6)),(a(),l(c,null,{default:n(()=>[d(o,{id:"mermaid-18",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BLine%20needs%20a%20route%5D%20--%3E%20B%7Broute%20mode%3F%7D%0A%20%20%20%20B%20--%3E%7Cdirect%20%2F%20manhattan%20%2F%20manual%7C%20C%5BFixed%20shape%3Cbr%2F%3Eno%20pathfinding%5D%0A%20%20%20%20B%20--%3E%7Cauto%2C%20smart%2C%20or%20grid%7C%20D%7BObstacle%3Cbr%2F%3Ein%20the%20way%3F%7D%0A%20%20%20%20D%20--%3E%7Cyes%7C%20E%5BDetour%20around%20it%5D%0A%20%20%20%20D%20--%3E%7Cno%7C%20F%7BForce%20channel%3Cbr%2F%3Ereferenced%3F%7D%0A%20%20%20%20E%20--%3E%20F%0A%20%20%20%20F%20--%3E%7Cyes%7C%20G%5BMust%20route%20through%20it%5D%0A%20%20%20%20F%20--%3E%7Cno%7C%20H%7BNearby%20trunk%20or%20channel%3Cbr%2F%3Eworth%20joining%3F%7D%0A%20%20%20%20H%20--%3E%7Cyes%2C%20cheaper%20overall%7C%20I%5BBundle%20into%20a%20shared%20lane%5D%0A%20%20%20%20H%20--%3E%7Cno%2C%20or%20not%20worth%20it%7C%20J%5BRoute%20independently%5D%0A%20%20%20%20G%20--%3E%20K%7BWould%20this%20cross%3Cbr%2F%3Eanother%20line's%20path%3F%7D%0A%20%20%20%20I%20--%3E%20K%0A%20%20%20%20J%20--%3E%20K%0A%20%20%20%20K%20--%3E%7Cyes%2C%20small%20detour%20avoids%20it%7C%20L%5BStep%20around%20the%20crossing%5D%0A%20%20%20%20K%20--%3E%7Cno%2C%20or%20detour%20too%20costly%7C%20M%5BFinal%20path%5D%0A%20%20%20%20L%20--%3E%20M%0A%20%20%20%20C%20--%3E%20M%0A%20%20%20%20M%20--%3E%20N%5BRegistered%3Cbr%2F%3Eother%20lines%20can%20now%20discover%20and%20bundle%20with%20this%20one%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>Two things worth calling out that a flowchart&#39;s yes/no boxes can&#39;t fully capture: bundling and crossing-avoidance are always <strong>cost comparisons</strong>, never hard rules: a line only joins a bundle or takes a detour when doing so is genuinely cheaper than the alternative. And this whole sequence runs for <em>every</em> line, repeatedly, until the arrangement settles, so the order you declared your lines in never affects the outcome.</p><hr><h2 id="obstacles" tabindex="-1">Obstacles <a class="header-anchor" href="#obstacles" aria-label="Permalink to &quot;Obstacles&quot;">​</a></h2><p>Any control with <code>obstacle: true</code> is something every <code>auto</code>/<code>smart</code>/<code>grid</code> line routes around automatically, no per-line config needed.</p><p><img src="'+u+'" alt="A line detouring around an obstacle box"></p><hr><h2 id="automatic-bundling" tabindex="-1">Automatic Bundling <a class="header-anchor" href="#automatic-bundling" aria-label="Permalink to &quot;Automatic Bundling&quot;">​</a></h2><p>Lines heading the same general direction, running close enough to each other, merge into a shared corridor (riding evenly-spaced lanes) and branch apart again where their destinations actually diverge. This is entirely automatic: no channel, no config, just lines that happen to be going the same way.</p><p><img src="'+g+'" alt="Three lines merging into a shared lane-separated corridor, then branching apart at their destinations"></p><hr><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p>A channel is an <strong>authored</strong> corridor: a region you draw yourself that lines are rewarded for traveling through (<code>mode: prefer</code>), penalized for entering (<code>avoid</code>), or required to use (<code>force</code>). Where automatic bundling only happens between lines that are already naturally close, a channel can pull a line off a path it wouldn&#39;t otherwise take, when the discount makes it worthwhile.</p><p><img src="'+p+'" alt="A line bending off its natural path to ride through an authored prefer channel"></p><hr><h2 id="crossing-avoidance" tabindex="-1">Crossing Avoidance <a class="header-anchor" href="#crossing-avoidance" aria-label="Permalink to &quot;Crossing Avoidance&quot;">​</a></h2><p>A line&#39;s path is penalized for cutting across another already-routed line&#39;s segment. It&#39;s a deterrent, not a wall: when stepping around is cheap, the router takes the detour; when the only alternative is a long way around, it crosses cleanly instead.</p><p><img src="'+m+'" alt="A line stepping around another line&#39;s path instead of crossing straight through it"></p><hr><h2 id="where-to-go-next" tabindex="-1">Where to Go Next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to Go Next&quot;">​</a></h2><ul><li><a href="./routing.html">Line Routing &amp; Channels</a>: every mode, field, and tunable default</li><li><a href="./line-overlay.html">Line Overlay</a>: per-line properties, styling, markers</li><li><a href="./quick-start.html">MSD Quick Start</a>: build your first MSD, UI-only</li><li><a href="./../../architecture/msd/routing.html">Routing Engine Architecture</a>: internals: registries, lane assignment, the discovery loop</li></ul>',20))])}const D=r(f,[["render",b]]);export{E as __pageData,D as default};
